describe("FE-7 server/admin/index.ts — one function per §7.1 route", () => {
  it("getStaff calls apiClient once against ENDPOINTS.ADMIN.STAFF with no init", async () => {
    const { getStaff } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    await getStaff();
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.STAFF);
  });

  it("enrollStaff POSTs the body verbatim as JSON", async () => {
    const { enrollStaff } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    const body = {
      email: "a@megaannum.ai", first_name: "A", last_name: "B", role: "RM" as const,
      notify: true,
    };
    await enrollStaff(body);
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.STAFF, {
      method: "POST", body: JSON.stringify(body),
    });
  });

  it("updateStaff PATCHes the target uid's endpoint", async () => {
    const { updateStaff } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    await updateStaff("uid-1", { role: "MOBO" });
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.STAFF_MEMBER("uid-1"), {
      method: "PATCH", body: JSON.stringify({ role: "MOBO" }),
    });
  });

  it("sendSetPasswordLink POSTs with an empty body", async () => {
    const { sendSetPasswordLink } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    await sendSetPasswordLink("uid-1");
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.STAFF_SET_PW_LINK("uid-1"), { method: "POST" });
  });

  it("getMatrix GETs the matrix endpoint with no init", async () => {
    const { getMatrix } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    await getMatrix();
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.ACCESS_MATRIX);
  });

  it("publishMatrix PUTs and ALWAYS includes base_published_at, null included", async () => {
    const { publishMatrix } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    await publishMatrix({ changes: [], base_published_at: null });
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.ACCESS_MATRIX, {
      method: "PUT", body: JSON.stringify({ changes: [], base_published_at: null }),
    });
    const [, init] = mockApiClient.mock.calls[0];
    expect(JSON.parse(init.body)).toHaveProperty("base_published_at", null);
  });

  it("getOverrides GETs the overrides endpoint", async () => {
    const { getOverrides } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    await getOverrides();
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.ACCESS_OVERRIDES);
  });

  it("grantOverride POSTs the override body", async () => {
    const { grantOverride } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    const body = { firebase_uid: "u1", page_id: "pc.model-management" as const, level: "EDIT" as const, reason: "x", expires_at: null };
    await grantOverride(body);
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.ACCESS_OVERRIDES, {
      method: "POST", body: JSON.stringify(body),
    });
  });

  it("revokeOverride DELETEs by id", async () => {
    const { revokeOverride } = await import("@/server/admin");
    const { ENDPOINTS } = await import("@/server/endpoints");
    await revokeOverride("ovr-1");
    expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.ACCESS_OVERRIDE("ovr-1"), { method: "DELETE" });
  });

  describe("getAudit query-string construction", () => {
    it("with {limit, before} appends both as query params", async () => {
      const { getAudit } = await import("@/server/admin");
      const { ENDPOINTS } = await import("@/server/endpoints");
      await getAudit({ limit: 50, before: "2026-07-01T00:00:00Z" });
      expect(mockApiClient).toHaveBeenCalledWith(
        `${ENDPOINTS.ADMIN.AUDIT}?limit=50&before=2026-07-01T00%3A00%3A00Z`,
      );
    });

    it("negative: with no args appends no query string", async () => {
      const { getAudit } = await import("@/server/admin");
      const { ENDPOINTS } = await import("@/server/endpoints");
      await getAudit();
      expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.AUDIT);
    });

    it("negative: an explicit undefined limit/before is treated as absent, not '0'/'undefined'", async () => {
      const { getAudit } = await import("@/server/admin");
      const { ENDPOINTS } = await import("@/server/endpoints");
      await getAudit({ limit: undefined, before: undefined });
      expect(mockApiClient).toHaveBeenCalledWith(ENDPOINTS.ADMIN.AUDIT);
    });
  });

  describe("negative — failure propagation", () => {
    it("a non-2xx from apiClient propagates as {success:false} with the status-derived code, not swallowed", async () => {
      mockApiClient.mockResolvedValueOnce({ success: false, error: "HTTP 409", code: "HTTP_409" });
      const { getStaff } = await import("@/server/admin");
      const result = await getStaff();
      expect(result).toEqual({ success: false, error: "HTTP 409", code: "HTTP_409" });
    });

    it("a 409 is distinguishable from a 422 and from a network error by code alone", async () => {
      mockApiClient
        .mockResolvedValueOnce({ success: false, error: "conflict", code: "HTTP_409" })
        .mockResolvedValueOnce({ success: false, error: "invalid", code: "HTTP_422" })
        .mockResolvedValueOnce({ success: false, error: "down", code: "NETWORK_ERROR" });
      const { publishMatrix } = await import("@/server/admin");
      const r1 = await publishMatrix({ changes: [], base_published_at: null });
      const r2 = await publishMatrix({ changes: [], base_published_at: null });
      const r3 = await publishMatrix({ changes: [], base_published_at: null });
      expect((r1 as { code: string }).code).toBe("HTTP_409");
      expect((r2 as { code: string }).code).toBe("HTTP_422");
      expect((r3 as { code: string }).code).toBe("NETWORK_ERROR");
    });
  });

  it("invariant: no action throws — every failure is a returned envelope, never a rejection", async () => {
    mockApiClient.mockRejectedValueOnce(new Error("boom"));
    const { getStaff } = await import("@/server/admin");
    // server/admin/index.ts itself does not try/catch (that is the actions.ts wrapper's
    // job, tested below) — this asserts apiClient's own contract (it never rejects) is
    // what server/admin relies on, by proving a rejection here is NOT silently swallowed
    // into a resolved envelope by this module (it must propagate to its caller, the
    // actions.ts wrapper, which is the layer that owns turning it into ACTION_ERROR).
    await expect(getStaff()).rejects.toThrow("boom");
  });
});

describe("FE-7 app/(roles)/admin/actions.ts — the route-local logging wrapper", () => {
  // Each test below vi.doMock's @/server/admin differently, then re-imports
  // @/app/(roles)/admin/actions. Without resetModules, the second import resolves
  // from the already-populated module registry (the first test's mock leaks in).
  beforeEach(() => {
    vi.resetModules();
  });

  it("forwards to server/admin and returns its result verbatim on success", async () => {
    vi.doMock("@/server/admin", () => ({
      getStaff: vi.fn(async () => ({ success: true, data: [] })),
    }));
    const { getStaff } = await import("@/app/(roles)/admin/actions");
    const result = await getStaff();
    expect(result).toEqual({ success: true, data: [] });
  });

  it("a thrown error from server/admin is funneled through toErrorResult as {success:false, code:'ACTION_ERROR'}, never propagated", async () => {
    vi.doMock("@/server/admin", () => ({
      getStaff: vi.fn(async () => {
        throw new Error("network down");
      }),
    }));
    const { getStaff } = await import("@/app/(roles)/admin/actions");
    const result = await getStaff();
    expect(result).toEqual({ success: false, error: "network down", code: "ACTION_ERROR" });
  });
});
